def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, 1.0 / (1.0 + rem) - 0.5 * (rem == bins), -np.inf)
    if bins.size > 0 and bins[-1] >= 1.0 - 1e-7 and bins[-1] >= item:
